// Generated by AI (UnitTest MCP)
//! Lifecycle tool definitions and dispatch.

use super::{ok, rendered, req_str};
use lodestar_core::Lodestar;
use serde_json::{json, Value};

pub(super) fn definitions() -> Vec<Value> {
    vec![
        json!({
            "name": "lodestar_stats",
            "description": "Goal/task/knowledge counts, including `total_tasks` (every task ever created, any status -- tells a `board`/`stalled` caller whether its own empty result means nothing has ever been set up, or that everything is genuinely clean) and `done_verdicts` (breaks `done_tasks` down by aligned/needs_human/drift/violation/unresolved -- `done` means shipped, not that conformance affirmed it); zero active goals also returns goal/import bootstrap actions.",
            "inputSchema": { "type": "object", "properties": {} }
        }),
        json!({
            "name": "model_telemetry",
            "description": "Token usage and cost observability for Lodestar's own model calls (decompose/judge/draft_question): lifetime calls/errors and prompt/completion/total token counts, overall and broken down per operation. Reads a durable local record, not a live model -- answers even when no model is configured or reachable.",
            "inputSchema": { "type": "object", "properties": {} }
        }),
        json!({
            "name": "backup_database",
            "description": "Create a verified online SQLite backup of the complete Lodestar intent plane. The destination must not already exist.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "path": { "type": "string", "description": "Destination path for the SQLite backup." }
                },
                "required": ["path"]
            }
        }),
        json!({
            "name": "reset_database",
            "description": "Destructively clear Lodestar designs/materialization history, constitution, tasks, bindings, conformance audit, and learned knowledge. Requires the exact confirmation token RESET LODESTAR and never touches MindLeak memory.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "confirm": { "type": "string", "description": "Must be exactly RESET LODESTAR." }
                },
                "required": ["confirm"]
            }
        }),
    ]
}

pub(super) fn dispatch(
    engine: &Lodestar,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "lodestar_stats" => Some((|| {
            let stats = engine.stats().map_err(|e| e.to_string())?;
            let mut markdown = format!(
                "| Intent Plane | Count |\n|---|--:|\n| Active goals | {} |\n| Open tasks | {} |\n| Claimed tasks | {} |\n| Done tasks | {} |\n| Total tasks (any status) | {} |\n| Active knowledge | {} |",
                stats.active_goals,
                stats.open_tasks,
                stats.claimed_tasks,
                stats.done_tasks,
                stats.total_tasks,
                stats.active_knowledge
            );
            let v = &stats.done_verdicts;
            markdown.push_str(&format!(
                "\n\n**Done tasks by verdict** - {} aligned, {} needs_human, {} drift",
                v.aligned, v.needs_human, v.drift
            ));
            if v.violation > 0 {
                markdown.push_str(&format!(", {} violation", v.violation));
            }
            if v.unresolved > 0 {
                markdown.push_str(&format!(
                    ", {} unresolved (no conformance record)",
                    v.unresolved
                ));
            }
            if let Some(next) = &stats.next_step {
                markdown.push_str(&format!("\n\n**Get started** - {}\n", next.summary));
                for action in &next.actions {
                    markdown.push_str(&format!(
                        "\n- `{}` with `action=\"{}\"`: {}",
                        action.tool, action.action, action.purpose
                    ));
                }
            }
            rendered(markdown, &stats)
        })()),
        "model_telemetry" => Some((|| {
            let snapshot = engine.model_telemetry().map_err(|e| e.to_string())?;
            let mut markdown = format!(
                "| Lodestar model calls | Count |\n|---|--:|\n| Total calls | {} |\n| Lifetime errors | {} |\n| Prompt tokens | {} |\n| Completion tokens | {} |\n| Total tokens | {} |\n",
                snapshot.total_calls,
                snapshot.total_errors,
                snapshot.total_prompt_tokens,
                snapshot.total_completion_tokens,
                snapshot.total_tokens
            );
            if !snapshot.by_operation.is_empty() {
                markdown.push_str(
                    "\n| Operation | Calls | Errors | Prompt tokens | Completion tokens | Total tokens | Avg ms |\n|---|--:|--:|--:|--:|--:|--:|\n",
                );
                for metric in &snapshot.by_operation {
                    markdown.push_str(&format!(
                        "| {} | {} | {} | {} | {} | {} | {:.1} |\n",
                        metric.operation,
                        metric.calls,
                        metric.errors,
                        metric.total_prompt_tokens,
                        metric.total_completion_tokens,
                        metric.total_tokens,
                        metric.avg_ms
                    ));
                }
            }
            rendered(markdown, &snapshot)
        })()),
        "backup_database" => Some((|| {
            let path = req_str(args, "path")?;
            engine.backup_database(path).map_err(|e| e.to_string())?;
            ok(&json!({ "backed_up": true, "path": path }))
        })()),
        "reset_database" => Some((|| {
            let outcome = engine
                .reset_database(req_str(args, "confirm")?)
                .map_err(|e| e.to_string())?;
            ok(&outcome)
        })()),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::super::call;
    use super::*;
    use lodestar_core::GoalKind;

    fn payload(result: Value) -> Value {
        serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap()
    }

    #[test]
    fn stats_and_active_knowledge_agree_after_retirement() {
        let engine = Lodestar::open_in_memory().unwrap();
        let retired = engine
            .record_knowledge("retired lesson", "{}", Some(720.0))
            .unwrap();
        engine
            .record_knowledge("active lesson", "{}", Some(720.0))
            .unwrap();
        engine
            .retire_knowledge(&retired.id, "Reviewer", "measured false", None)
            .unwrap();

        let active = payload(
            call(
                &engine,
                &json!({ "name": "active_knowledge", "arguments": {} }),
            )
            .unwrap(),
        );
        let stats = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(active["count"], json!(1));
        assert_eq!(
            stats["structuredContent"]["active_knowledge"],
            active["count"]
        );
    }

    /// `total_tasks` is the one number that tells a `board`/`stalled` caller
    /// seeing an empty result whether nothing has ever been created here or
    /// everything is genuinely clean -- it must count a task regardless of
    /// which status it is currently in, unlike `open_tasks`.
    #[test]
    fn total_tasks_is_reported_and_the_markdown_names_it() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Counted", "count every task", None)
            .unwrap();
        engine.create_task(&goal.id, "Work", "done").unwrap();

        let stats = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(stats["structuredContent"]["total_tasks"], json!(1));
        assert!(stats["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("Total tasks"));
    }

    /// gaps.d/done-does-not-mean-aligned.md: `done_tasks` alone cannot tell an
    /// automated `aligned` affirmation apart from a human-resolved override.
    /// The override/unresolved buckets are exercised at the store layer
    /// (crates/lodestar-core/src/store/lifecycle.rs), which has the private
    /// access needed to force those states directly; this proves the wiring
    /// through the real public claim/complete path reports the same field.
    #[test]
    fn done_verdicts_are_reported_and_the_markdown_names_them() {
        let engine = Lodestar::open_in_memory().unwrap();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship search", "add FTS", None)
            .unwrap();
        let task = engine
            .create_task(&goal.id, "wire fts", "tests pass")
            .unwrap();
        engine
            .link_goal_to_artifact(
                &goal.id,
                &["artifact:src/search.rs".to_string()],
                lodestar_core::ArtifactBindingMode::Governed,
            )
            .unwrap();
        engine.claim_task(&task.id, "agent-a", 300).unwrap();
        let claim = engine.store().get_task(&task.id).unwrap().unwrap();
        let evidence = lodestar_core::ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task.id.clone()),
            agent_id: "agent-a".into(),
            started_at: claim.claim_started_at.unwrap(),
            ended_at: lodestar_core::now_unix(),
            changed_node_ids: vec!["artifact:src/search.rs".into()],
            failed_node_ids: Vec::new(),
            execution_ids: vec!["execution:proof".into()],
            successful_execution_ids: vec!["execution:proof".into()],
            commit_ids: Vec::new(),
            summary: "wired fts".into(),
            provenance: vec![
                lodestar_core::EvidenceProvenance {
                    source_id: "agent:agent-a".into(),
                    target_id: "execution:proof".into(),
                    relation: "observed".into(),
                },
                lodestar_core::EvidenceProvenance {
                    source_id: "execution:proof".into(),
                    target_id: "artifact:src/search.rs".into(),
                    relation: "modified".into(),
                },
            ],
        };
        let check = engine.check_conformance(&evidence, Some(&task.id)).unwrap();
        assert!(
            engine
                .complete_task(&task.id, "agent-a", &evidence, &check, None)
                .unwrap()
                .completed
        );

        let stats = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(
            stats["structuredContent"]["done_verdicts"]["aligned"],
            json!(1)
        );
        assert!(stats["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("1 aligned"));
    }

    #[test]
    fn zero_goal_stats_return_actionable_bootstrap_routes() {
        let engine = Lodestar::open_in_memory().unwrap();

        let result = call(
            &engine,
            &json!({ "name": "lodestar_stats", "arguments": {} }),
        )
        .unwrap();
        let markdown = result["content"][0]["text"].as_str().unwrap();

        assert!(markdown.contains("**Get started**"));
        assert!(markdown.contains("`constitution_define` with `action=\"goal\"`"));
        assert!(markdown.contains("`constitution_define` with `action=\"import\"`"));
        assert_eq!(
            result["structuredContent"]["next_step"]["reason"],
            "no_active_goals"
        );
    }

    #[test]
    fn model_telemetry_reports_calls_and_tokens_per_operation() {
        let engine = Lodestar::open_in_memory().unwrap();
        engine.record_model_call(
            "decompose",
            true,
            42,
            Some("glm4:9b"),
            Some(lodestar_core::TokenUsage {
                prompt_tokens: Some(100),
                completion_tokens: Some(20),
                total_tokens: Some(120),
            }),
        );
        engine.record_model_call("judge", false, 5, Some("glm4:9b"), None);

        let result = call(
            &engine,
            &json!({ "name": "model_telemetry", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(result["structuredContent"]["total_calls"], json!(2));
        assert_eq!(result["structuredContent"]["total_errors"], json!(1));
        assert_eq!(result["structuredContent"]["total_tokens"], json!(120));
        let markdown = result["content"][0]["text"].as_str().unwrap();
        assert!(markdown.contains("decompose"));
        assert!(markdown.contains("judge"));
    }

    /// A fresh Lodestar with no model calls ever made must report a zeroed
    /// snapshot -- never an error -- since "nothing recorded yet" is a fact,
    /// not a failure, and the table is created lazily.
    #[test]
    fn model_telemetry_on_a_fresh_engine_is_zero_not_an_error() {
        let engine = Lodestar::open_in_memory().unwrap();

        let result = call(
            &engine,
            &json!({ "name": "model_telemetry", "arguments": {} }),
        )
        .unwrap();

        assert_eq!(result["structuredContent"]["total_calls"], json!(0));
        assert_eq!(result["structuredContent"]["by_operation"], json!([]));
    }

    #[test]
    fn lifecycle_tools_backup_and_require_lodestar_reset_token() {
        let engine = Lodestar::open_in_memory().unwrap();
        engine
            .define_goal(
                GoalKind::Invariant,
                "Keep intent durable",
                "Never erase intent with memory reset",
                None,
            )
            .unwrap();
        let path =
            std::env::temp_dir().join(format!("lodestar-mcp-backup-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);

        call(
            &engine,
            &json!({
                "name": "backup_database",
                "arguments": { "path": path.to_str().unwrap() }
            }),
        )
        .unwrap();
        let restored = Lodestar::open(path.to_str().unwrap()).unwrap();
        assert_eq!(restored.get_constitution().unwrap().len(), 1);
        drop(restored);
        std::fs::remove_file(path).unwrap();

        let rejected = call(
            &engine,
            &json!({
                "name": "reset_database",
                "arguments": { "confirm": "RESET MINDLEAK" }
            }),
        )
        .unwrap_err();
        assert!(rejected.contains("RESET LODESTAR"));
        call(
            &engine,
            &json!({
                "name": "reset_database",
                "arguments": { "confirm": "RESET LODESTAR" }
            }),
        )
        .unwrap();
        assert!(engine.get_constitution().unwrap().is_empty());
    }
}
